#pragma once
// Kerning pairs for the faces the font atlas is cut from (data: src/userland/font_kerning.cpp, generated by
// metal/tools/mkkern.py from the same DejaVu files mkfont.py rasterises). The atlas has each glyph's advance;
// these are the adjustments between particular neighbours -- "AV", "To", "y." -- in font units.
#include <cstdint>

namespace aios::userland::fonts {

struct KernPair {
  uint32_t pair;   // left code point << 16 | right code point
  int16_t adj;     // font units: negative pulls the right glyph in
};

struct KernTable {
  const KernPair* pairs;
  int count;
  int units_per_em;
};

// In the order of kKern. Mono is not here: a monospace face is not kerned.
enum class KernFamily : uint8_t {
  Sans, SansBold, SansItalic, SansBoldItalic, Serif, SerifBold, SerifItalic, SerifBoldItalic
};

extern const KernTable kKern[];

// The adjustment between `left` and `right` in `family`, in pixels at `px`; 0 when the pair is not kerned.
inline float kern_px(KernFamily family, uint32_t left, uint32_t right, float px) {
  if (left > 0xFFFF || right > 0xFFFF) return 0.0f;
  const KernTable& t = kKern[static_cast<int>(family)];
  const uint32_t key = (left << 16) | right;
  int lo = 0, hi = t.count;
  while (lo < hi) {
    const int mid = (lo + hi) / 2;
    if (t.pairs[mid].pair < key) lo = mid + 1;
    else hi = mid;
  }
  if (lo < t.count && t.pairs[lo].pair == key) return (float)t.pairs[lo].adj * px / (float)t.units_per_em;
  return 0.0f;
}

}  // namespace aios::userland::fonts
